      sourcesContent: ["import { BaseSort } from \"../baseSort\";\n\nexport class Cocktail extends BaseSort {\n  // is there a way to respect sorted sections?\n  public static title = \"Cocktail Sort\";\n  public direction: number;\n  public start: number;\n  public end: number;\n  public shortCircuit: boolean = false;\n\n  public setUp() {\n    this.start = 0;\n    this.end = this.length - 1;\n    this.direction = 1;\n  }\n\n  public setUpNext() {\n    if (this.direction) {\n      if (this.comparisonNode === this.end) {\n        this.placed.push(this.end);\n        this.end--;\n        this.baseNode--;\n        this.comparisonNode--;\n        this.direction = 0;\n        if (this.ordered && this.shortCircuit) {\n          this.setDone();\n        } else {\n          this.ordered = true;\n        }\n      } else {\n        this.baseNode++;\n        this.comparisonNode++;\n      }\n    } else {\n      if (this.baseNode === this.start) {\n        this.placed.push(this.start);\n        this.direction = 1;\n        this.start++;\n        this.baseNode++;\n        this.comparisonNode++;\n        if (this.ordered && this.shortCircuit) {\n          this.setDone();\n        } else {\n          this.ordered = true;\n        }\n      } else {\n        this.baseNode--;\n        this.comparisonNode--;\n      }\n    }\n    if (!(this.start < this.end)) {\n      this.setDone();\n    }\n  }\n}\n"]
