      sourcesContent: ["import { range } from \"lodash\";\n\nexport interface IValueType {\n  title: string;\n  generate(n: number): any[];\n}\n\nexport const Random: IValueType = {\n  title: \"Random\",\n  generate(n: number): number[] {\n    const spread = n * 2;\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      values.push(Math.floor(Math.random() * spread));\n    }\n    return values;\n  },\n};\n\nexport const Integer: IValueType = {\n  generate: (n: number) => {\n    return range(0, n);\n  },\n  title: \"Range\",\n};\n\nexport const FewUnique: IValueType = {\n  title: \"Few Values\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      values.push(i % 5);\n    }\n    return values;\n  },\n};\n\nexport const AllBut2Equal: IValueType = {\n  title: \"All But 2 Equal\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n - 2; i++) {\n      values.push(n / 2);\n    }\n    values.push(2);\n    values.push(n - 2);\n    values.sort();\n    return values;\n  },\n};\n\nexport const Equal: IValueType = {\n  title: \"Equal\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      values.push(n / 2);\n    }\n    return values;\n  },\n};\n\nexport const Logarithmic: IValueType = {\n  title: \"Logarithmic\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = (i + 1) / 8;\n      const num = Math.log(j);\n      values.push(Math.floor(num * 10));\n    }\n    return values;\n  },\n};\n\nexport const Quadratic: IValueType = {\n  title: \"Quadratic\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 10 * (i / n) - 5;\n      const num = j * j;\n      values.push(Math.floor(num * 2));\n    }\n    return values;\n  },\n};\n\nexport const Exponential: IValueType = {\n  title: \"Exponential\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 10 * (i / n) - 5;\n      const num = Math.pow(2, j);\n      values.push(Math.floor(num * 2));\n    }\n    return values;\n  },\n};\n\nexport const Cubic: IValueType = {\n  title: \"Cubic\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 4 * (i / n) - 2;\n      const num = j * j * j;\n      values.push(Math.floor(num * 3));\n    }\n    return values;\n  },\n};\n\nexport const Quintic: IValueType = {\n  title: \"Quintic\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 2 * (i / n) - 1;\n      const num = j * j * j * j * j;\n      values.push(Math.floor(num * 30));\n    }\n    return values;\n  },\n};\n\nexport const Sin: IValueType = {\n  title: \"Sin\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 12 * (i / n) - 6;\n      const num = Math.sin(j);\n      values.push(Math.floor(num * 30));\n    }\n    return values;\n  },\n};\n\nexport const Root: IValueType = {\n  title: \"Root\",\n  generate(n: number): number[] {\n    const values = [];\n    for (let i = 0; i < n; i++) {\n      const j = 5 * (i / n);\n      const num = Math.sqrt(j);\n      values.push(Math.floor(num * 15));\n    }\n    return values;\n  },\n};\n"]
